detaileddescription.para:
Typical usage: main(intargc,char*argv[]){
StringMap<llvm::cl::Option*>&opts=llvm::cl::getRegisteredOptions();
assert(opts.count("help")==1)
opts["help"]->setDescription("Showalphabeticalhelpinformation")
//Morecode
llvm::cl::ParseCommandLineOptions(argc,argv);
//Morecode
}

A range of all SubCommand pointers registered with the parser.

Typical usage: main(intargc,char*argv[]){
llvm::cl::ParseCommandLineOptions(argc,argv);
for(auto*S:llvm::cl::getRegisteredSubcommands()){
if(*S){
std::cout<<"Executingsubcommand:"<<S->getName()<<std::endl;
//Executesomefunctionbasedonthename...
}
}
}
